#!/usr/bin/env node
// Builds specs/<feature>/tabelas.dbml (to paste into dbdiagram.io) from:
//   - source: the DBML generated by Prisma (dbml/schema.dbml) — what exists today on the branch;
//   - tabelas.filtro.json: what the owner wants to see (table groups and notes);
//   - tabelas.planejado.dbml (optional): new or changed tables the plan expects and the schema does not have yet.
// With "base" in the filter, compares with the same source on the base branch (git show) and labels each table.
// Text written into tabelas.dbml is generated content and stays in pt-BR.
//
//   node tables-dbml.mjs <feature-dir>            writes tabelas.dbml — refuses if it has unabsorbed hand edits
//   node tables-dbml.mjs <feature-dir> --check    does not write; exits 1 if tabelas.dbml is stale
//   node tables-dbml.mjs <feature-dir> --force    writes even over hand edits (only after absorbing them)
//
// The owner may edit tabelas.dbml in dbdiagram.io. The script never applies those edits: it only detects them (the
// content no longer matches the signature it wrote) and stops. Understanding and absorbing them is the agent's job.
//
// Filter format: .claude/skills/speckit-tables/SKILL.md

import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';

const fail = (message) => {
  console.error(message);
  process.exit(2);
};

const [featureDir, flag] = process.argv.slice(2);
if (!featureDir) fail('usage: tables-dbml.mjs <feature-dir> [--check]');
const filterFile = path.join(featureDir, 'tabelas.filtro.json');
if (!fs.existsSync(filterFile)) fail(`missing ${filterFile}: create it with /speckit-tables`);

// Filters written before the English tooling used Portuguese keys.
const rawFilter = JSON.parse(fs.readFileSync(filterFile, 'utf8'));
const filter = {
  title: rawFilter.title ?? rawFilter.titulo,
  project: rawFilter.project ?? rawFilter.projeto,
  source: rawFilter.source ?? rawFilter.fonte ?? 'dbml/schema.dbml',
  base: rawFilter.base,
  baseLabel: rawFilter.baseLabel ?? rawFilter.baseRotulo,
  planned: rawFilter.planned ?? rawFilter.planejado,
  groups: rawFilter.groups ?? rawFilter.grupos ?? {},
  notes: rawFilter.notes ?? rawFilter.notas ?? {},
};
const repoRoot = execFileSync('git', ['rev-parse', '--show-toplevel'], { encoding: 'utf8' }).trim();
const sourceFile = path.join(repoRoot, filter.source);
if (!fs.existsSync(sourceFile)) fail(`source not found: ${sourceFile} (run "npx prisma generate")`);
const baseLabel = filter.baseLabel ?? filter.base;

// ───────────── reading DBML ─────────────

function parseDbml(text) {
  const tables = new Map();
  const enums = new Map();
  const refs = [];
  const blockPattern = /^(Table|Enum)\s+"?([\w.]+)"?(\s*\[[^\]]*\])?\s*\{\n([\s\S]*?)^\}/gm;
  let match;
  while ((match = blockPattern.exec(text))) {
    const block = { name: match[2], body: match[4].replace(/\s+$/, '') };
    (match[1] === 'Table' ? tables : enums).set(block.name, block);
  }
  for (const line of text.split('\n')) if (/^Ref\b/.test(line.trim())) refs.push(line.trim());
  return { tables, enums, refs };
}

function columnLines(body) {
  const columns = [];
  let nestedBlocks = 0;
  for (const line of body.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    if (/^(indexes|Note)\s*[{:]/.test(trimmed) && trimmed.endsWith('{')) {
      nestedBlocks++;
      continue;
    }
    if (nestedBlocks) {
      if (trimmed === '}') nestedBlocks--;
      continue;
    }
    if (/^Note\s*:/.test(trimmed)) continue;
    const column = trimmed.match(/^"?(\w+)"?\s+("?[\w.()]+"?)/);
    if (column) columns.push({ name: column[1], type: column[2].replace(/"/g, '').replace(/\(.*/, ''), line });
  }
  return columns;
}

const source = parseDbml(fs.readFileSync(sourceFile, 'utf8'));
const plannedFile = filter.planned ? path.join(featureDir, filter.planned) : null;
const planned = plannedFile && fs.existsSync(plannedFile) ? parseDbml(fs.readFileSync(plannedFile, 'utf8')) : parseDbml('');

let base = null;
if (filter.base) {
  try {
    base = parseDbml(
      execFileSync('git', ['show', `${filter.base}:${filter.source}`], { encoding: 'utf8', cwd: repoRoot, stdio: ['ignore', 'pipe', 'ignore'] }),
    );
  } catch {
    console.warn(`warning: could not read ${filter.source} at "${filter.base}"; no comparison with the base`);
  }
}

// Prisma relation fields (e.g. "credential UserCredential") are not columns and are dropped. Whether a type is a
// relation is decided inside its own document: the same name can be a table in one (on the base branch) and an enum
// in another (on the feature branch).
const contextOf = (...documents) => ({
  tables: new Set(documents.flatMap((document) => [...document.tables.keys()])),
  enums: new Set(documents.flatMap((document) => [...document.enums.keys()])),
});
const sourceContext = contextOf(source);
const plannedContext = contextOf(source, planned);
const baseContext = base ? contextOf(base) : null;
const withoutRelations = (body, context) =>
  body
    .split('\n')
    .filter((line) => {
      const column = line.match(/^\s+"?\w+"?\s+"?(\w+)"?/);
      return !(column && context.tables.has(column[1]) && !context.enums.has(column[1]));
    })
    .join('\n');

// ───────────── selection ─────────────

const errors = [];
const warnings = [];
const selectedNames = [...new Set(Object.values(filter.groups).flat())];
const selected = new Map(); // name → { body, origin: 'source' | 'planned' }
for (const name of selectedNames) {
  if (planned.tables.has(name)) selected.set(name, { body: withoutRelations(planned.tables.get(name).body, plannedContext), origin: 'planned' });
  else if (source.tables.has(name)) selected.set(name, { body: withoutRelations(source.tables.get(name).body, sourceContext), origin: 'source' });
  else errors.push(`"${name}" is in the filter but exists neither in the source nor in the planned file`);
}
for (const name of planned.tables.keys()) {
  if (!selected.has(name)) warnings.push(`"${name}" is in the planned file but outside the filter groups (not shown)`);
}

// ───────────── status against the base ─────────────

const withoutNote = (line) => line.trim().replace(/,?\s*note:\s*'(?:[^'\\]|\\.)*'/g, '').replace(/\[\s*\]/, '').trim();
const normalized = (body) =>
  columnLines(body)
    .map((column) => withoutNote(column.line))
    .sort()
    .join('\n');
const columnsOf = (body) => new Map(columnLines(body).map((column) => [column.name, withoutNote(column.line)]));
const sourceBody = (name) => withoutRelations(source.tables.get(name).body, sourceContext);
const baseBody = (name) => withoutRelations(base.tables.get(name).body, baseContext);

function summarizeChange(fromBody, toBody) {
  const before = columnsOf(fromBody);
  const after = columnsOf(toBody);
  const added = [...after.keys()].filter((name) => !before.has(name));
  const removed = [...before.keys()].filter((name) => !after.has(name));
  const changed = [...after.keys()].filter((name) => before.has(name) && before.get(name) !== after.get(name));
  return [
    added.length ? `+${added.join(', +')}` : '',
    removed.length ? `-${removed.join(', -')}` : '',
    changed.length ? `~${changed.join(', ~')}` : '',
  ]
    .filter(Boolean)
    .join('; ');
}

// Status notes are generated content: pt-BR.
function statusOf(name, table) {
  const current = source.tables.has(name) ? sourceBody(name) : null;
  if (table.origin === 'planned') {
    if (!current) return 'PLANEJADA (ainda não existe)';
    const change = summarizeChange(current, table.body);
    if (!change) warnings.push(`"${name}" in the planned file already matches the schema: it was implemented, remove it from the planned file`);
    return change ? `PLANEJADA, muda a atual: ${change}` : 'PLANEJADA, igual à atual (tirar do planejado)';
  }
  if (!base) return '';
  if (!base.tables.has(name)) return `NOVA desde ${baseLabel}`;
  if (normalized(baseBody(name)) === normalized(current)) return `sem mudança desde ${baseLabel}`;
  return `ALTERADA desde ${baseLabel}: ${summarizeChange(baseBody(name), current)}`;
}

// ───────────── assembly ─────────────

const quote = (text) => String(text).replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\n/g, ' ');
const usedEnums = new Set();
const finalColumns = new Map();
const sections = [];

for (const [name, table] of selected) {
  const columns = columnLines(table.body);
  finalColumns.set(name, new Set(columns.map((column) => column.name)));
  const output = [];
  let hasNote = false;
  for (let line of table.body.split('\n').filter((candidate) => candidate.trim() !== '')) {
    if (/^\s+Note\s*:/.test(line)) hasNote = true;
    const column = columns.find((candidate) => candidate.line === line);
    if (column) {
      if (source.enums.has(column.type) || planned.enums.has(column.type)) usedEnums.add(column.type);
      const note = filter.notes[`${name}.${column.name}`];
      if (note) line = /\]\s*$/.test(line) ? line.replace(/\]\s*$/, `, note: '${quote(note)}']`) : `${line} [note: '${quote(note)}']`;
      for (const ref of line.matchAll(/ref:\s*[<>-]+\s*"?(\w+)"?\./g)) {
        if (!selected.has(ref[1])) errors.push(`${name}.${column.name} references "${ref[1]}", which is outside the filter`);
      }
    }
    output.push(line.startsWith('  indexes') ? `\n${line}` : line);
  }
  const noteText = [statusOf(name, table), filter.notes[name]].filter(Boolean).join(' · ');
  if (noteText && hasNote) warnings.push(`"${name}" already has a Note in the planned file; the filter note and status were not added`);
  else if (noteText) output.push(`\n  Note: '${quote(noteText)}'`);
  sections.push(`Table ${name} {\n${output.join('\n')}\n}\n`);
}

for (const name of [...usedEnums].sort()) {
  const enumBlock = planned.enums.get(name) ?? source.enums.get(name);
  sections.push(`Enum ${name} {\n${enumBlock.body}\n}\n`);
}

const finalRefs = [];
const columnsExist = (table, columns) =>
  columns.split(',').every((column) => finalColumns.get(table)?.has(column.trim().replace(/"/g, '')));
for (const ref of [...planned.refs, ...source.refs]) {
  const match = ref.match(/^Ref[^:]*:\s*"?(\w+)"?\.\(?([\w", ]+)\)?\s*[<>-]+\s*"?(\w+)"?\.\(?([\w", ]+)\)?/);
  if (!match) continue;
  const [, fromTable, fromColumns, toTable, toColumns] = match;
  if (!selected.has(fromTable) || !selected.has(toTable)) continue;
  if (!columnsExist(fromTable, fromColumns) || !columnsExist(toTable, toColumns)) continue; // column removed by the planned file
  if (!finalRefs.includes(ref)) finalRefs.push(ref);
}
sections.push(finalRefs.join('\n'), '');
for (const [group, tables] of Object.entries(filter.groups)) {
  sections.push(`TableGroup ${group} {\n${tables.map((table) => `  ${table}`).join('\n')}\n}\n`);
}

const removedSinceBase = base ? [...base.tables.keys()].filter((name) => !source.tables.has(name)) : [];
const touchedOutsideFilter = base
  ? [...source.tables.keys()].filter(
      (name) => !selected.has(name) && (!base.tables.has(name) || normalized(baseBody(name)) !== normalized(sourceBody(name))),
    )
  : [];

// Header is generated content: pt-BR.
const header = [
  `// ${filter.title ?? 'Tabelas da feature'}`,
  `// GERADO por .specify/scripts/node/tables-dbml.mjs — não edite aqui. Edite ${path.basename(filterFile)}${filter.planned ? ` e ${filter.planned}` : ''} e gere de novo.`,
  `// Fonte: ${filter.source}${filter.base ? ` · comparado com ${baseLabel} (${filter.base})` : ''}. Colar em dbdiagram.io.`,
  '// Campos de relação do Prisma foram retirados; as ligações estão nos Ref. O gerador do Prisma não exporta índice único',
  '// parcial, gatilho, CHECK nem tipo do banco (@db.Timestamptz, @db.Char…): mudança só nisso aparece como "sem mudança".',
  removedSinceBase.length ? `// Removidas desde ${baseLabel}: ${removedSinceBase.join(', ')}.` : null,
  '',
  `Project ${filter.project ?? 'feature'} {`,
  "  database_type: 'PostgreSQL'",
  '}',
  '',
]
  .filter((line) => line !== null)
  .join('\n');

// Removes whole comment lines (newline included), so the signature line does not leave a blank line behind.
const withoutComments = (text) => text.replace(/\r\n/g, '\n').replace(/^\/\/ .*(\n|$)/gm, '');
const signatureOf = (text) => createHash('sha256').update(withoutComments(text)).digest('hex').slice(0, 16);
const SIGNATURE_PATTERN = /^\/\/ assinatura: ([0-9a-f]{16})/m;

const body = `${header}\n${sections.join('\n')}`;
// The signature line is generated content: pt-BR.
const output = `// assinatura: ${signatureOf(body)} — editou no dbdiagram? A próxima geração para e pede para absorver a mudança.\n${body}`;
const outputFile = path.join(featureDir, 'tabelas.dbml');

// A file without a signature was generated before the guard existed and is treated as unedited.
function hasHandEdits(file) {
  if (!fs.existsSync(file)) return false;
  const current = fs.readFileSync(file, 'utf8');
  const recorded = current.match(SIGNATURE_PATTERN)?.[1];
  return Boolean(recorded) && recorded !== signatureOf(current);
}

if (errors.length) {
  console.error(`${errors.length} error(s):\n${errors.map((error) => `- ${error}`).join('\n')}`);
  process.exit(1);
}
for (const warning of warnings) console.warn(`warning: ${warning}`);
if (touchedOutsideFilter.length) console.warn(`warning: touched since ${baseLabel} and outside the filter: ${touchedOutsideFilter.join(', ')}`);

if (flag === '--check' || flag === '--checar') {
  const current = fs.existsSync(outputFile) ? fs.readFileSync(outputFile, 'utf8') : '';
  if (hasHandEdits(outputFile)) {
    console.log('tabelas.dbml has hand edits not absorbed yet');
    process.exit(1);
  }
  if (withoutComments(current) !== withoutComments(output)) {
    console.log('tabelas.dbml is stale');
    process.exit(1);
  }
  console.log('tabelas.dbml is up to date');
} else if (hasHandEdits(outputFile) && flag !== '--force') {
  console.error(
    'tabelas.dbml has hand edits not absorbed yet; nothing was written.\n' +
      `Read them (git diff -- ${outputFile}), judge them and move what is valid into ${filter.planned ?? 'tabelas.planejado.dbml'} ` +
      'or tabelas.filtro.json; then run again with --force.',
  );
  process.exit(1);
} else {
  fs.writeFileSync(outputFile, output);
  console.log(`generated ${outputFile}: ${selected.size} table(s), ${usedEnums.size} enum(s), ${finalRefs.length} ref(s)`);
}
